use serde::{Deserialize,Serialize}; use super::{digest,error::{AdmissionError,AdmissionErrorKind,Result},subject::SubjectId};
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)] pub enum SourceKind{Repository,Generator,Observation,Human,External}
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct Provenance{pub subject:SubjectId,pub source:SourceKind,pub source_id:String,pub observed_revision:String,pub parents:Vec<String>}
impl Provenance{pub fn validate(&self)->Result<()>{self.subject.validate()?;if self.source_id.trim().is_empty(){return Err(AdmissionError::new(AdmissionErrorKind::InvalidProvenance,"provenance.source.empty","source id required").subject(self.subject.key()))}if self.observed_revision!=self.subject.revision{return Err(AdmissionError::new(AdmissionErrorKind::InvalidProvenance,"provenance.revision.mismatch","observation must bind exact subject revision").subject(self.subject.key()))}Ok(())}pub fn digest(&self)->String{let mut p=vec![self.subject.key(),self.source_id.clone(),self.observed_revision.clone()];p.extend(self.parents.clone());digest::digest(&p.iter().map(String::as_str).collect::<Vec<_>>())}}